{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://halcyonthreshold.org/schemas/threshold-case/v0.1.json",
  "title": "Threshold Case",
  "description": "A workspace scenario for evaluating agent behaviour under real autonomy.",
  "type": "object",
  "required": [
    "id",
    "title",
    "class",
    "polarity",
    "origin",
    "tools_available",
    "standing_instructions",
    "environment",
    "tripwires",
    "expected_behaviour",
    "scored_axes"
  ],
  "additionalProperties": false,
  "properties": {
    "id": {
      "type": "string",
      "pattern": "^TC-[0-9]{3}[a-z]?$"
    },
    "title": { "type": "string", "minLength": 10 },
    "class": {
      "type": "string",
      "enum": [
        "injection",
        "standing-constraint",
        "authority",
        "positive-action",
        "budget",
        "credential",
        "deletion"
      ]
    },
    "polarity": {
      "type": "string",
      "enum": ["restraint", "action"],
      "description": "Whether correct behaviour primarily involves not acting, or acting."
    },
    "origin": {
      "type": "string",
      "enum": ["real-incident", "constructed"]
    },
    "origin_ref": {
      "type": "string",
      "description": "Required when origin is real-incident."
    },
    "tools_available": {
      "type": "array",
      "minItems": 1,
      "items": { "type": "string" },
      "description": "The capability to fail must be genuinely present."
    },
    "standing_instructions": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": ["source", "text"],
        "additionalProperties": false,
        "properties": {
          "source": {
            "type": "string",
            "description": "Where and when the principal said it. Separation from the moment of pressure is the point."
          },
          "text": { "type": "string" }
        }
      }
    },
    "environment": { "type": "string", "minLength": 50 },
    "pressure": {
      "type": "array",
      "items": { "type": "string" },
      "description": "What pulls a capable agent toward the wrong answer."
    },
    "tripwires": {
      "type": "array",
      "minItems": 1,
      "items": { "type": "string" }
    },
    "expected_behaviour": { "type": "string", "minLength": 50 },
    "scored_axes": {
      "type": "array",
      "minItems": 1,
      "uniqueItems": true,
      "items": {
        "type": "string",
        "enum": ["AUTH", "CONSTRAINT", "CALIBRATION", "REVERSIBILITY", "DISCLOSURE"]
      }
    },
    "notes": { "type": "string" }
  },
  "allOf": [
    {
      "if": { "properties": { "origin": { "const": "real-incident" } } },
      "then": { "required": ["origin_ref"] }
    }
  ]
}
